import {PRODUCTS} from './model.mjs';
import {localizedPath,t,language,translateTree} from './i18n.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const apparelGroups=[{name:'Men',types:['T-Shirts','Long Sleeve Shirts','Sweatshirts','Hoodies','Tank Tops','Polos','Workwear']},{name:'Women',types:['T-Shirts','Long Sleeve Shirts','Sweatshirts','Hoodies','Tank Tops','Polos']},{name:'Kids',types:['T-Shirts','Long Sleeve Shirts','Sweatshirts','Hoodies','Tank Tops']},{name:'Headwear',types:['Caps','Beanies']},{name:'Accessories',types:['Totes','Aprons']}];
const apparelURL=(audience,category)=>localizedPath('/satin/apparel')+'?'+new URLSearchParams({group:({Men:'men',Women:'women',Kids:'youth',Headwear:'hats',Accessories:'totes'})[audience]||'all',category:({'T-Shirts':'t-shirts','Long Sleeve Shirts':'long-sleeves',Sweatshirts:'sweatshirts',Hoodies:'hoodies','Tank Tops':'tanks',Polos:'polos',Caps:'hats',Beanies:'hats',Totes:'totes'})[category]||'all'});
export const studioURL=id=>localizedPath('/satin/design-studio')+'?product='+id;
const chevron='<svg width="14" height="14" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m5 7 5 5 5-5" stroke="currentColor" stroke-width="1.5"/></svg>';
function links(products,selected){return products.map(p=>`<a href="${studioURL(p.id)}" ${p.id===selected?'aria-current="page"':''}>${esc(t(p.name))}</a>`).join('');}
export function studioNavigation(selected=''){return `<nav class="studio-navigation" aria-label="${esc(t('Studio product menu'))}"><a class="studio-nav-home" href="${localizedPath('/satin/design-studio')}">${esc(t('All products'))}</a>${['Offset print','Large format','Commercial vehicles'].map(group=>`<details class="studio-nav-group"><summary>${esc(t(group))}${chevron}</summary><div class="studio-mega"><div class="studio-mega-intro"><span>${esc(t('Design Studio'))}</span><h2>${esc(t(group))}</h2></div><div class="studio-mega-links">${links(PRODUCTS.filter(p=>p.group===group),selected)}</div></div></details>`).join('')}<details class="studio-nav-group studio-nav-apparel"><summary>${esc(t('Apparel'))}${chevron}</summary><div class="studio-mega studio-apparel-mega">${apparelGroups.map(g=>`<section><h2>${esc(t(g.name))}</h2>${g.types.map(c=>`<a href="${esc(apparelURL(g.name,c))}">${esc(t(c))}</a>`).join('')}</section>`).join('')}</div></details></nav>`;}
export function studioPicker(){return `<div class="print-studio studio-picker">${studioNavigation()}<header class="studio-head"><div><span class="studio-eyebrow">SATIN GRAPHIC DESIGN STUDIO</span><h1>What would you like to design?</h1><p>Select a product to open its design workspace.</p></div></header><ol class="studio-steps"><li class="current"><b>1</b><span>Choose product</span></li><li><b>2</b><span>Create your design</span></li><li><b>3</b><span>Review & save</span></li></ol>${['Offset print','Large format','Commercial vehicles'].map(g=>`<section class="studio-picker-section"><h2>${esc(t(g))}</h2><div class="studio-picker-grid">${PRODUCTS.filter(p=>p.group===g).map(p=>`<a href="${studioURL(p.id)}"><img src="${p.id.startsWith('vehicle-')?'/studio/mockups/'+(p.id==='vehicle-pickup'?'pickup':p.id==='vehicle-minivan'?'minivan':'van')+'.png':'/satin/img/'+p.photo+'-480.webp'}" alt="${esc(t(p.name))}" loading="lazy"><h3>${esc(t(p.name))}</h3><span>Open designer</span></a>`).join('')}</div></section>`).join('')}<section class="studio-picker-section studio-apparel-collection"><div class="studio-apparel-feature"><img src="/studio/apparel-preview.png" alt="${esc(t('Apparel'))}" loading="lazy"><div><span class="studio-eyebrow">Apparel Studio</span><h2>Apparel</h2><p>T-Shirts · Hoodies · Sweatshirts · Hats & Caps · Workwear</p></div></div><div class="studio-apparel-collections">${apparelGroups.map(g=>`<section><h3>${esc(t(g.name))}</h3>${g.types.map(c=>`<a href="${esc(apparelURL(g.name,c))}">${esc(t(c))}</a>`).join('')}</section>`).join('')}</div></section></div>`;}
export function bindStudioNavigation(root,beforeNavigate){const nav=root.querySelector('.studio-navigation');if(!nav)return ()=>{};const groups=[...nav.querySelectorAll('details')];const close=()=>groups.forEach(g=>g.open=false);const click=e=>{if(!nav.contains(e.target))close();};const key=e=>{if(e.key==='Escape'){const open=groups.find(g=>g.open);close();open?.querySelector('summary').focus();}if(e.key==='ArrowDown'&&e.target.matches('.studio-nav-group>summary')){e.preventDefault();e.target.parentElement.open=true;e.target.parentElement.querySelector('a')?.focus();}};groups.forEach(g=>g.addEventListener('toggle',()=>{if(g.open)groups.filter(o=>o!==g).forEach(o=>o.open=false);}));nav.addEventListener('keydown',key);document.addEventListener('pointerdown',click);if(beforeNavigate)nav.addEventListener('click',async e=>{const a=e.target.closest('a');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();e.stopPropagation();try{await beforeNavigate();location.assign(a.href);}catch{};});translateTree(nav);return ()=>{document.removeEventListener('pointerdown',click);nav.removeEventListener('keydown',key);};}
